// Async server component that fetches the current user's profile.
// Profile data is user-specific, so it is intentionally not cached with
// "use cache"; render it inside a <Suspense> boundary so it streams at
// request time (required with cacheComponents enabled).
interface User {
  name: string
  email: string
}

async function getUserProfile(): Promise<User> {
  try {
    const res = await fetch('/api/users/profile')
    if (!res.ok) {
      throw new Error(`Failed to fetch user profile: ${res.status}`)
    }
    return res.json()
  } catch {
    // Return mock data for build time
    return { name: 'Sample User', email: 'user@example.com' }
  }
}

export default async function UserProfile() {
  const user = await getUserProfile()

  return (
    <div>
      <h2>User Profile</h2>
      <div>Name: {user.name}</div>
      <div>Email: {user.email}</div>
    </div>
  )
}

